  "kind": "blueprint",
  "preview": {
   "organize.py": "\"\"\"Generated by Blockwise. Verify behavior before use.\"\"\"\nimport shutil\nimport sys\nfrom pathlib import Path\nCATEGORIES = {'.jpg': 'images', '.jpeg': 'images', '.png': 'images', '.gif': 'images', '.pdf': 'documents', '.docx': 'documents', '.txt': 'documents', '.md': 'documents', '.csv': 'data', '.json': 'data', '.xlsx': 'data', '.zip': 'archives', '.mp3': 'audio', '.mp4': 'video'}\n\n\ndef category_for(path: Path) -> str:\n    return CATEGORIES.get(path.suffix.lower(), 'other')\n\n\ndef plan_moves(folder: Path) -> list:\n    \"\"\"Requirements:\nOnly plain files directly in the folder; hidden files and subfolders stay put.\"\"\"\n    moves = []\n    for entry in sorted(folder.iterdir(), key=lambda entry: entry.name.lower()):\n        if entry.is_file() and (not entry.name.startswith('.')):\n            moves.append({'source': entry, 'target': folder / category_for(entry) / entry.name})\n    return moves\n\n\ndef describe(moves: list) -> str:\n    return '\\n'.join([move['source'].name + ' -> ' + move['target'].parent.name + '/' for move in moves])\n\n\ndef apply_moves(moves: list) -> int:\n    \"\"\"Requirements:\nNever overwrite: a file whose target already exists is skipped.\"\"\"\n    moved = 0\n    for move in moves:\n        if move['target'].exists():\n            print('skip ' + move['source'].name + ': already in ' + move['target'].parent.name + '/')\n            continue\n        move['target'].parent.mkdir(exist_ok=True)\n        shutil.move(move['source'], move['target'])\n        moved += 1\n    return moved\n\n\ndef dry_run(moves: list) -> int:\n    print(f'Dry run: {len(moves)} file(s) would move. Add --apply to move them.')\n    return 0\n\n\ndef main(args: list) -> int:\n    \"\"\"Requirements:\nUsage: FOLDER [--apply]. Without --apply nothing is moved.\"\"\"\n    if not args or len(args) > 2 or (len(args) == 2 and args[1] != '--apply'):\n        print('usage: organize.py FOLDER [--apply]')\n        return 2\n    if not Path(args[0]).is_dir():\n        print(f'error: {args[0]} is not a folder')\n        return 1\n    moves = plan_moves(Path(args[0]))\n    if not moves:\n        print('Nothing to organize.')\n        return 0\n    print(describe(moves))\n    if len(args) == 1:\n        return dry_run(moves)\n    print(f'Moved {apply_moves(moves)} file(s).')\n    return 0\n\n\nif __name__ == '__main__':\n    sys.exit(main(sys.argv[1:]))\n"
  }
