   "store.py": "\"\"\"Generated by Blockwise. Verify behavior before use.\"\"\"\nimport json\nimport sys\nSTORE = 'store.json'\n\n\ndef load(path: str) -> dict:\n    \"\"\"Requirements:\nA missing file means an empty store. A file that is not a JSON object of text values is an error, and is never overwritten.\"\"\"\n    try:\n        with open(path, encoding='utf-8') as handle:\n            text = handle.read()\n    except FileNotFoundError:\n        return {}\n    try:\n        data = json.loads(text)\n    except ValueError:\n        raise ValueError(f'{path} is not valid JSON; fix or remove it')\n    if not isinstance(data, dict) or not all((isinstance(value, str) for value in data.values())):\n        raise ValueError(f'{path} is not a key-value store; fix or remove it')\n    return data\n\n\ndef save(path: str, data: dict) -> None:\n    with open(path, 'w', encoding='utf-8') as handle:\n        json.dump(data, handle, indent=2, sort_keys=True)\n\n\ndef format_entries(data: dict) -> str:\n    if not data:\n        return '(empty)'\n    return '\\n'.join((f'{key} = {data[key]}' for key in sorted(data)))\n\n\ndef require_key(data: dict, key: str) -> None:\n    if key not in data:\n        raise LookupError(f'no key {key}')\n\n\ndef set_value(data: dict, key: str, value: str) -> int:\n    data.update({key: value})\n    save(STORE, data)\n    print(f'{key} saved.')\n    return 0\n\n\ndef get_value(data: dict, key: str) -> int:\n    require_key(data, key)\n    print(data[key])\n    return 0\n\n\ndef delete_value(data: dict, key: str) -> int:\n    require_key(data, key)\n    data.pop(key)\n    save(STORE, data)\n    print(f'{key} deleted.')\n    return 0\n\n\ndef main(args: list) -> int:\n    \"\"\"Requirements:\nCommands: set KEY VALUE, get KEY, delete KEY, list. Returns the exit code.\"\"\"\n    try:\n        data = load(STORE)\n        if not args or args[0] == 'list':\n            print(format_entries(data))\n        elif args[0] == 'set' and len(args) == 3:\n            return set_value(data, args[1], args[2])\n        elif args[0] == 'get' and len(args) == 2:\n            return get_value(data, args[1])\n        elif args[0] == 'delete' and len(args) == 2:\n            return delete_value(data, args[1])\n        else:\n            print('usage: store.py [set KEY VALUE | get KEY | delete KEY | list]')\n            return 2\n    except (LookupError, OSError, ValueError) as error:\n        print(f'error: {error}')\n        return 1\n    return 0\n\n\nif __name__ == '__main__':\n    sys.exit(main(sys.argv[1:]))\n"
