  "kind": "blueprint",
  "preview": {
   "todo.py": "\"\"\"Generated by Blockwise. Verify behavior before use.\"\"\"\nimport json\nimport sys\nSTORE = 'todo.json'\n\n\ndef load_items(path: str) -> list:\n    \"\"\"Requirements:\nA missing file means an empty list. A file that is not a JSON list of to-do items is an error, and is never overwritten.\"\"\"\n    try:\n        with open(path, encoding='utf-8') as handle:\n            text = handle.read()\n    except FileNotFoundError:\n        return []\n    try:\n        items = json.loads(text)\n    except ValueError:\n        raise ValueError(f'{path} is not valid JSON; fix or remove it')\n    if not isinstance(items, list) or not all((isinstance(item, dict) and isinstance(item.get('text'), str) and isinstance(item.get('done'), bool) for item in items)):\n        raise ValueError(f'{path} is not a to-do list; fix or remove it')\n    return items\n\n\ndef save_items(path: str, items: list) -> None:\n    with open(path, 'w', encoding='utf-8') as handle:\n        json.dump(items, handle, indent=2)\n\n\ndef add_item(items: list, text: str) -> list:\n    if not text.strip():\n        raise ValueError('text must not be empty')\n    items.append({'text': text.strip(), 'done': False})\n    return items\n\n\ndef complete_item(items: list, number: int) -> list:\n    if number < 1 or number > len(items):\n        raise IndexError(f'no item {number}')\n    items[number - 1].update(done=True)\n    return items\n\n\ndef item_number(args: list) -> int:\n    \"\"\"Requirements:\ndone takes exactly one whole number.\"\"\"\n    if len(args) != 2 or not args[1].isdecimal():\n        raise ValueError('done needs one item number, like: done 2')\n    return int(args[1])\n\n\ndef format_items(items: list) -> str:\n    if not items:\n        return 'Nothing to do.'\n    lines = []\n    number = 0\n    for item in items:\n        number += 1\n        mark = 'x' if item['done'] else ' '\n        lines.append(str(number) + '. [' + mark + '] ' + item['text'])\n    return '\\n'.join(lines)\n\n\ndef main(args: list) -> int:\n    \"\"\"Requirements:\nCommands: list, add TEXT, done NUMBER. Returns the exit code.\"\"\"\n    try:\n        items = load_items(STORE)\n        if not args or args[0] == 'list':\n            print(format_items(items))\n        elif args[0] == 'add':\n            save_items(STORE, add_item(items, ' '.join(args[1:])))\n            print('Added.')\n        elif args[0] == 'done':\n            save_items(STORE, complete_item(items, item_number(args)))\n            print('Marked done.')\n        else:\n            print('usage: todo.py [list | add TEXT | done NUMBER]')\n            return 2\n    except (IndexError, OSError, ValueError) as error:\n        print(f'error: {error}')\n        return 1\n    return 0\n\n\nif __name__ == '__main__':\n    sys.exit(main(sys.argv[1:]))\n"
  }
