   "url_check.py": "\"\"\"Generated by Blockwise. Verify behavior before use.\"\"\"\nimport ipaddress\nimport sys\nfrom urllib.parse import urlsplit\nALLOWED = ('example.com', 'api.example.com')\n\n\ndef is_ip_literal(host: str) -> bool:\n    try:\n        ipaddress.ip_address(host)\n    except ValueError:\n        return False\n    return True\n\n\ndef is_internal_host(host: str) -> bool:\n    \"\"\"Requirements:\nIP literals, numeric shorthands like 127.1 or 0x7f.1, localhost and internal-only names are never allowed, even if allowlisted.\"\"\"\n    if is_ip_literal(host):\n        return True\n    if all((label.isdigit() or label.startswith('0x') for label in host.split('.'))):\n        return True\n    return host == 'localhost' or host.endswith(('.localhost', '.local', '.internal', '.localdomain', '.home.arpa'))\n\n\ndef url_host(url: str) -> str:\n    \"\"\"Requirements:\nReturn the lower-case host of a well-formed http(s) URL without credentials, or raise ValueError.\"\"\"\n    if not url.isprintable() or ' ' in url or '\\\\' in url:\n        raise ValueError('refused: the URL contains spaces, backslashes or control characters')\n    parts = urlsplit(url)\n    if parts.scheme not in ('http', 'https'):\n        raise ValueError('refused: only http and https URLs are allowed')\n    if parts.username is not None or parts.password is not None:\n        raise ValueError('refused: the URL contains credentials')\n    host = (parts.hostname or '').rstrip('.')\n    if not host:\n        raise ValueError('refused: the URL has no host')\n    port = parts.port\n    return host\n\n\ndef check_url(url: str, allowed_hosts: list) -> str:\n    \"\"\"Requirements:\nReturn the URL unchanged only if every check passes; otherwise raise ValueError. Hosts must match the allowlist exactly (no substring, prefix or suffix matching). Never resolves names or makes a request.\"\"\"\n    host = url_host(url)\n    if is_internal_host(host):\n        raise ValueError(f'refused: {host} is an internal or numeric address')\n    if host not in [name.lower().rstrip('.') for name in allowed_hosts]:\n        raise ValueError(f'refused: {host} is not on the allowlist')\n    return url\n\n\ndef main(args: list) -> int:\n    \"\"\"Requirements:\nUsage: URL. Prints 'allowed: URL' or the refusal; checks against ALLOWED.\"\"\"\n    if len(args) != 1:\n        print('usage: url_check.py URL')\n        return 2\n    try:\n        check_url(args[0], list(ALLOWED))\n    except ValueError as error:\n        print(error)\n        return 1\n    print(f'allowed: {args[0]}')\n    return 0\n\n\nif __name__ == '__main__':\n    sys.exit(main(sys.argv[1:]))\n"
